<?php require_once __DIR__.'/../config/config.php';role_required(['production']);$pageTitle='Production Issues';$rows=db()->query('SELECT * FROM issues ORDER BY year DESC,volume DESC,issue DESC')->fetchAll();include __DIR__.'/../includes/header.php';?><h1 class="title">Production Issues</h1><div class="panel"><table><tr><th>Volume</th><th>Issue</th><th>Year</th><th>Publication Date</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['volume'])?></td><td><?=e($r['issue'])?></td><td><?=e($r['year'])?></td><td><?=e($r['publication_date'])?></td></tr><?php endforeach;?></table></div><?php include __DIR__.'/../includes/footer.php';?>